window.AUTH=window.AUTH||{};window.AUTH["09-1036"]={"d":"09-1036","id":"2010/09-1036","n":"Henderson v. Shinseki","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the respondent","date":"","url":"https://www.justice.gov/osg/media/198091/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/henderson-v-shinseki-brief-merits","n":81}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep562/usrep562428/usrep562428.pdf","tr":true,"items":[{"t":"case","label":"Arbaugh v. Y&H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"op":4,"ar":3,"sum":"The Court held that the number-of-employees requirement is an element of the merits of a Title VII claim, not a jurisdictional limitation.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Bailey v. West","cite":"160 F.3d 1360","y":1998,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/160/1360/","by":{"0":"23, 24"}},{"t":"case","label":"Barnhart v. Peabody Coal Co.","cite":"537 U.S. 149","y":2003,"id":"2002/01-705","sc":1,"sum":"The Court held that the Commissioner's initial assignments made after October 1, 1993, are valid despite their untimeliness. The Court reasoned that a statute directing official action needed more than a mandatory \"shall\" before the grant of power would be read to expire when the job was supposed to be completed.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Bowen v. City of New York","cite":"476 U.S. 467","y":1986,"id":"1985/84-1923","sc":1,"op":1,"ar":2,"sum":"The Social Security Act provides benefits to disabled persons under two programs administered by the Social Security Administration (SSA): the Social Security Disability Insurance Program (SSD) and the Supplemental Security Income Program (SSI). Regulations for both programs establish a five-step \"sequential evaluation\" process for determining eligibility for benefits. The initial determination of whether an …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Bowles v. Russell","cite":"551 U.S. 205","y":2007,"id":"2006/06-5306","sc":1,"op":15,"ar":35,"sum":"The Court ruled that, even though Bowles was relying on the mistaken order of the District Court, the Circuit Court was correct to dismiss his untimely appeal.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"sum":"The Court affirmed the lower court's decision and ruled for Gardner. The Court held that Section 1151 contains no language requiring proof of fault, and it rejected the Government's claims that the requirement was implicit in the language of the statute.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Butler v. Derwinski","cite":"960 F.2d 139","y":1992,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/960/139/","by":{"0":"23"}},{"t":"case","label":"Cellular Telecomms. & Internet Ass’n v. FCC","cite":"330 F.3d 502","y":2003,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/330/502/","by":{"0":"18"}},{"t":"case","label":"Cullens v. Gober","cite":"14 Vet. App. 234","y":2001,"url":"https://www.courtlistener.com/c/Vet.%20App./14/234/","by":{"0":"32"}},{"t":"case","label":"Dudley v. Derwinski","cite":"2 Vet. App. 602","y":1992,"url":"https://www.courtlistener.com/c/Vet.%20App./2/602/","by":{"0":"23"}},{"t":"case","label":"eBay, Inc. v. MercExchange, L.L.C.","cite":"547 U.S. 388","y":2006,"id":"2005/05-130","sc":1,"sum":"Held that the appeals court's general rule was an unwarranted departure from the traditional four-part test applied to determine whether an injunction is necessary.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Eberhart v. United States","cite":"546 U.S. 12","y":2005,"id":"2005/04-9949","sc":1,"op":4,"sum":"The Court held that Federal Rule of Criminal Procedure 33, which creates a seven-day limit for filing a motion for a new trial that is not based on newly discovered evidence, was not a jurisdictional rule but rather a claim-processing one.","sumSrc":"Oyez","by":{"0":"10"}},{"t":"case","label":"FEC v. NRA Political Victory Fund","cite":"513 U.S. 88","y":1994,"id":"1994/93-1151","sc":1,"sum":"Petitioner Federal Election Commission (FEC) brought this civil action against respondents seeking to enforce a provision of the Federal Election Campaign Act of 1971 (FECA). The District Court ruled against respondents. The Court of Appeals reversed and entered its judgment on October 22, 1993. Without first seeking or obtaining the Solicitor General's authorization, the FEC filed in its own name a petition for a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Florilli Corp. v. Pena","cite":"118 F.3d 1212","y":1997,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/118/1212/","by":{"0":"18"}},{"t":"case","label":"Former Employees of Motorola Ceramic Prods. v. United States","cite":"336 F.3d 1360","y":2003,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/336/1360/","by":{"0":"32"}},{"t":"case","label":"Forshey v. Principi","cite":"284 F.3d 1335","y":2002,"url":"https://www.courtlistener.com/c/F.3d/284/1335/","by":{"0":"16, 28"}},{"t":"case","label":"Griggs v. Provident Consumer Disc. Co.","cite":"459 U.S. 56","y":1982,"id":"1982/82-5082","sc":1,"sum":"The Court of Appeals' analysis of Rule 4(a)(4) is contrary to the language and purposes of the 1979 amendments to the Rules of Appellate Procedure. Prior to 1979, if a notice of appeal was fied pending disposition of a motion to vacate, alter, or amend the judgment it was generally held that the district court retained jurisdiction to decide the motion and the notice of appeal was adequate for purposes of beginning …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10, 11"}},{"t":"case","label":"Holmes Group, Inc. v. Vornado Air Circulation Sys., Inc.","cite":"535 U.S. 826","y":2002,"id":"2001/01-408","sc":1,"sum":"The Court held that the appellate could not assert jurisdiction over such a case.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"INS v. National Ctr. for Immigrants’ Rights, Inc.","cite":"502 U.S. 183","y":1991,"id":"1991/90-1090","sc":1,"op":1,"sum":"The regulation on its face is consistent with the Attorney General's statutory authority.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"Irwin v. Department of Veterans Affairs","cite":"498 U.S. 89","y":1990,"id":"1990/89-5867","sc":1,"ar":2,"sum":"The Supreme Court held that lower courts have consistently held that notice to an attorney's office qualifies as notice to the client. \"The practical effect of a contrary rule would be to encourage factual disputes about when actual notice was received, and thereby create uncertainty in an area of the law where certainty is much to be desired,\" wrote Chief Justice Rehnquist.","sumSrc":"Oyez","by":{"0":"6, 14"}},{"t":"case","label":"Jama v. ICE","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"John R. Sand & Gravel Co. v. United States","cite":"552 U.S. 130","y":2008,"id":"2007/06-1164","sc":1,"op":1,"sum":"In a seven-member majority opinion written by Justice Stephen G. Breyer, the Court upheld the Federal Circuit ruling that the statute of limitations was \"jurisdictional,\" or a predicate for court authority. Breyer referred to roughly five decades of the Court's case law to determine that the doctrine of stare decisis required it to follow the time limit and dismiss John R. Sand's claim.","sumSrc":"Oyez","by":{"0":"19, 27"}},{"t":"case","label":"Jones v. Bock","cite":"549 U.S. 199","y":2007,"id":"2006/05-7058","sc":1,"sum":"The Court ruled unanimously that the Sixth Circuit's rules for exhaustion of administrative remedies were not required by the Prisoner Litigation Reform Act. The opinion by Chief Justice John Roberts held that prisoners bring civil rights lawsuits do not need to demonstrate that they have already exhausted all administrative remedies.","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Kelly v. Nicholson","cite":"463 F.3d 1349","y":2006,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/463/1349/","by":{"0":"32"}},{"t":"case","label":"Kontrick v. Ryan","cite":"540 U.S. 443","y":2004,"id":"2003/02-819","sc":1,"op":3,"sum":"The Court held that Kontrick lost the right to invoke Rule 4004's time limitation because he did so after the bankruptcy court reached the merits of Ryan's objection. The Court rejected Kontrick's claim that Rule 4004 is \"jurisdictional\" and that it trumps other considerations whenever raised in proceedings.","sumSrc":"Oyez","by":{"0":"10"}},{"t":"case","label":"Lamie v. United States Tr.","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"sum":"According to Justice Anthony Kennedy's opinion for the Court: \"The statute is awkward, and even ungrammatical; but that does not make it ambiguous on the point at issue.\" The Court ruled that though the Act's deletion of the words \"or to the debtor's attorney\" from the Bankruptcy Code had rendered a sentence grammatically incorrect, the Act should still be interpreted according to the plain meaning of its text, however awkward.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"by":{"0":"24"}},{"t":"case","label":"Reed Elsevier, Inc. v. Muchnick","cite":"130 S. Ct. 1237","y":2010,"id":"2009/08-103","sc":1,"op":3,"ar":2,"sum":"The Court held that the registration requirement of Section 411(a) of the Copyright Act is a precondition to filing a copyright infringement claim.","sumSrc":"Oyez","by":{"0":"11, 12, 13, 26"}},{"t":"case","label":"Shinseki v. Sanders","cite":"129 S. Ct. 1696","y":2009,"id":"2008/07-1209","sc":1,"sum":"The Court found that the lower court's framework for evaluating VA (Veterans' Affairs) notice errors conflicted with the established law that the Veterans Court \"take due account of the rule of the prejudicial error.\"","sumSrc":"Oyez","by":{"0":"2, 5, 8, 15, 28, 29"}},{"t":"case","label":"Stone v. INS","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"op":1,"ar":7,"sum":"A timely motion for reconsideration of a BIA decision does not toll the running of § 106(a)(1)'s 90-day period.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 26"}},{"t":"case","label":"United States v. Beggerly","cite":"524 U.S. 38","y":1998,"id":"1997/97-731","sc":1,"sum":"The Court held that the Court of Appeals erred in concluding that this was a sufficient basis to justify reopening the judgment. \"[A]n independent action should be available only to prevent a grave miscarriage of justice,\" wrote Chief Justice Rehnquist, \"it should be obvious that [the Beggerlys'] allegations do not nearly approach this demanding standard.\" The Court also concluded that the Court of Appeals extension of the Quiet Title Act's statutory period by equitable tolling was unwarranted, given its generous nature.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"United States v. Curry","cite":"47 U.S. 106","y":1848,"id":"scdb/1848-018","sc":1,"sum":"The 9th section of the act of -26th May, 1824, relative to the action of the Attorney-General in cases of appeal, is only directory, and its non-observance does not vitiate an appeal, provided it be taken by the district attorney and sanctioned in this court by the Attorney-General.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"10"}},{"t":"case","label":"United States v. Denedo","cite":"129 S. Ct. 2213","y":2009,"id":"2008/08-267","sc":1,"sum":"The Court held that the Navy-Marine Corps Court of Criminal Appeals (NMCCA) retained jurisdiction under the All Writs Act to consider coram nobis petitions that alleged a prior judgment of conviction was fundamentally flawed.","sumSrc":"Oyez","by":{"0":"5, 27"}},{"t":"case","label":"United States v. Locke","cite":"471 U.S. 84","y":1985,"id":"1984/83-1394","sc":1,"sum":"Section 314 of the Federal Land Policy and Management Act of 1976 (FLPMA) establishes a federal recording system that is designed to rid federal lands of stale mining claims and to provide federal land managers with up-to-date information that allows them to make informed land management decisions. Section 314(b) requires that mining claims located prior to FLPMA's enactment be initially recorded with the Bureau of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8, 31"}},{"t":"case","label":"United States v. Rodriguez","cite":"67 M.J. 110","y":2009,"url":"https://www.courtlistener.com/c/M.J./67/110/","by":{"0":"27"}},{"t":"case","label":"Walters v. National Ass’n of Radiation Survivors","cite":"473 U.S. 305","y":1985,"id":"1984/84-571","sc":1,"op":1,"sum":"Title 38 U. S. C. § 3404(c) limits to $10 the fee that may be paid an attorney or agent who represents a veteran seeking benefits from the Veterans' Administration (VA) for service-connected death or disability. Appellees (two veterans' organizations, three individual veterans, and a veteran's widow) brought an action in Federal District Court claiming that the fee limitation denied them any realistic opportunity to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Weinberger v. Salfi","cite":"422 U.S. 749","y":1975,"id":"1974/74-214","sc":1,"op":1,"sum":"After her husband of less than six months died, appellee widow filed applications for mother's Social Security insurance benefits for herself and child's insurance benefits for her daughter by a previous marriage, but the Social Security Administration (SSA), both initially and on reconsideration at the regional level, denied the applications on the basis of the duration-of-relationship requirements of the Social …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Zipes v. TWA","cite":"455 U.S. 385","y":1982,"id":"1981/78-1545","sc":1,"op":1,"ar":2,"sum":"In 1970, the union then representing flight attendants employed by respondent Trans World Airlines, Inc. (TWA), brought a federal-court class action alleging that TWA practiced unlawful sex discrimination in violation of Title VII of the Civil Rights Act of 1964 by its policy of grounding all female flight attendants who became mothers while their male counterparts who became fathers were permitted to continue …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 25"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["criminal-jury-venue","Criminal Jury and Venue Clause"],["treason","Treason Clause"],["treason-punishment","Punishment of Treason Clause"]],"by":{"0":"5, 24, 27"}},{"t":"law","label":"Equal Access to Justice Act, Pub. L. No. 96-481","url":"https://www.govinfo.gov/link/statute/94/2325","by":{"0":"32"}},{"t":"usc","label":"28 U.S.C. § 2409a","url":"https://www.law.cornell.edu/uscode/text/28/2409a","by":{"0":"30"}},{"t":"law","label":"Pub. L. No. 103-446","url":"https://www.govinfo.gov/link/statute/108/4670","by":{"0":"23"}},{"t":"law","label":"Veterans’ Judicial Review Act, Pub. L. No. 100-687","url":"https://www.govinfo.gov/link/statute/102/4105","by":{"0":"19"}},{"t":"usc","label":"8 U.S.C. § 1105a","url":"https://www.law.cornell.edu/uscode/text/8/1105a","subs":["(a)(1)"],"by":{"0":"26"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(b)(1)"],"by":{"0":"26"}},{"t":"usc","label":"17 U.S.C. § 411","url":"https://www.law.cornell.edu/uscode/text/17/411","subs":["(a)"],"by":{"0":"11, 12"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","stext":{"head":"§1291. Final decisions of district courts","paras":[[0,"The courts of appeals (other than the United States Court of Appeals for the Federal Circuit) shall have jurisdiction of appeals from all final decisions of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, except where a direct review may be had in the Supreme Court. The jurisdiction of the United States Court of Appeals for the Federal Circuit shall be limited to the jurisdiction described in sections 1292(c) and (d) and 1295 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1291?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1291. Final decisions of district courts","tname":"Judiciary and Judicial Procedure","by":{"0":"25"}},{"t":"usc","label":"28 U.S.C. § 2101","url":"https://www.law.cornell.edu/uscode/text/28/2101","subs":["(c)"],"by":{"0":"30, 26"}},{"t":"usc","label":"28 U.S.C. § 2107","url":"https://www.law.cornell.edu/uscode/text/28/2107","subs":["(a)","(c)"],"stext":{"head":"§2107. Time for appeal to court of appeals","paras":[[0,"(a) Except as otherwise provided in this section, no appeal shall bring any judgment, order or decree in an action, suit or proceeding of a civil nature before a court of appeals for review unless notice of appeal is filed, within thirty days after the entry of such judgment, order or decree."],[0,"(b) In any such action, suit, or proceeding, the time as to all parties shall be 60 days from such entry if one of the parties is—"],[1,"(1) the United States;"],[1,"(2) a United States agency;"],[1,"(3) a United States officer or employee sued in an official capacity; or"],[1,"(4) a current or former United States officer or employee sued in an individual capacity for an act or omission occurring in connection with duties performed on behalf of the United States, including all instances in which the United States represents that officer or employee when the judgment, order, or decree is entered or files the appeal for that officer or employee."],[0,"(c) The district court may, upon motion filed not later than 30 days after the expiration of the time otherwise set for bringing appeal, extend the time for appeal upon a showing of excusable neglect or good cause. In addition, if the district court finds—"],[1,"(1) that a party entitled to notice of the entry of a judgment or order did not receive such notice from the clerk or any party within 21 days of its entry, and"],[1,"(2) that no party would be prejudiced,"],[0,"the district court may, upon motion filed within 180 days after entry of the judgment or order or within 14 days after receipt of such notice, whichever is earlier, reopen the time for appeal for a period of 14 days from the date of entry of the order reopening the time for appeal."],[0,"(d) This section shall not apply to bankruptcy matters or other proceedings under Title 11."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2107?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":2,"head":"§2107. Time for appeal to court of appeals","tname":"Judiciary and Judicial Procedure","by":{"0":"9, 12, 25, 30, 9, 9"}},{"t":"usc","label":"28 U.S.C. § 2344","url":"https://www.law.cornell.edu/uscode/text/28/2344","stext":{"head":"§2344. Review of orders; time; notice; contents of petition; service","paras":[[0,"On the entry of a final order reviewable under this chapter, the agency shall promptly give notice thereof by service or publication in accordance with its rules. Any party aggrieved by the final order may, within 60 days after its entry, file a petition to review the order in the court of appeals wherein venue lies. The action shall be against the United States. The petition shall contain a concise statement of—"],[1,"(1) the nature of the proceedings as to which review is sought;"],[1,"(2) the facts on which venue is based;"],[1,"(3) the grounds on which relief is sought; and"],[1,"(4) the relief prayed."],[0,"The petitioner shall attach to the petition, as exhibits, copies of the order, report, or decision of the agency. The clerk shall serve a true copy of the petition on the agency and on the Attorney General by registered mail, with request for a return receipt."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2344?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2344. Review of orders; time; notice; contents of petition; service","tname":"Judiciary and Judicial Procedure","by":{"0":"18, 30"}},{"t":"usc","label":"38 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/38/301","subs":["(c)(5)"],"stext":{"head":"§301. Department","paras":[[0,"(a) The Department of Veterans Affairs is an executive department of the United States."],[0,"(b) The purpose of the Department is to administer the laws providing benefits and other services to veterans and the dependents and the beneficiaries of veterans."],[0,"(c) The Department is composed of the following:"],[1,"(1) The Office of the Secretary."],[1,"(2) The Veterans Health Administration."],[1,"(3) The Veterans Benefits Administration."],[1,"(4) The National Cemetery Administration."],[1,"(5) The Board of Veterans' Appeals."],[1,"(6) The Veterans' Canteen Service."],[1,"(7) The Board of Contract Appeals."],[1,"(8) Such other offices and agencies as are established or designated by law or by the President or the Secretary."],[1,"(9) Any office, agency, or activity under the control or supervision of any element named in paragraphs (1) through (8)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/301?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§301. Department","tname":"Veterans' Benefits","by":{"0":"2"}},{"t":"usc","label":"38 U.S.C. § 5100","url":"https://www.law.cornell.edu/uscode/text/38/5100","by":{"0":"2"}},{"t":"usc","label":"38 U.S.C. § 5104","url":"https://www.law.cornell.edu/uscode/text/38/5104","subs":["(a)"],"by":{"0":"33"}},{"t":"usc","label":"38 U.S.C. § 5108","url":"https://www.law.cornell.edu/uscode/text/38/5108","stext":{"head":"§5108. Supplemental claims","paras":[[0,"(a) In General.—If new and relevant evidence is presented or secured with respect to a supplemental claim, the Secretary shall readjudicate the claim taking into consideration all of the evidence of record."],[0,"(b) Duty to Assist.—(1) If a claimant, in connection with a supplemental claim, reasonably identifies existing records, whether or not in the custody of a Federal department or agency, the Secretary shall assist the claimant in obtaining the records in accordance with section 5103A of this title."],[0,"(2) Assistance under paragraph (1) shall not be predicated upon a finding that new and relevant evidence has been presented or secured."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/5108?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§5108. Supplemental claims","tname":"Veterans' Benefits","by":{"0":"34"}},{"t":"usc","label":"38 U.S.C. § 5109A","url":"https://www.law.cornell.edu/uscode/text/38/5109A","stext":{"head":"§5109A. Revision of decisions on grounds of clear and unmistakable error","paras":[[0,"(a) A decision by the Secretary under this chapter is subject to revision on the grounds of clear and unmistakable error. If evidence establishes the error, the prior decision shall be reversed or revised."],[0,"(b) For the purposes of authorizing benefits, a rating or other adjudicative decision that constitutes a reversal or revision of a prior decision on the grounds of clear and unmistakable error has the same effect as if the decision had been made on the date of the prior decision."],[0,"(c) Review to determine whether clear and unmistakable error exists in a case may be instituted by the Secretary on the Secretary's own motion or upon request of the claimant."],[0,"(d) A request for revision of a decision of the Secretary based on clear and unmistakable error may be made at any time after that decision is made."],[0,"(e) Such a request shall be submitted to the Secretary and shall be decided in the same manner as any other claim."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/5109A?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§5109A. Revision of decisions on grounds of clear and unmistakable error","tname":"Veterans' Benefits","by":{"0":"34"}},{"t":"usc","label":"38 U.S.C. § 7101","url":"https://www.law.cornell.edu/uscode/text/38/7101","stext":{"head":"§7101. Composition of Board of Veterans' Appeals","paras":[[0,"(a) There is in the Department a Board of Veterans' Appeals (hereinafter in this chapter referred to as the \"Board\"). The Board is under the administrative control and supervision of a chairman directly responsible to the Secretary. The Board shall consist of a Chairman, a Vice Chairman, and such number of members as may be found necessary in order to conduct hearings and dispose of appeals properly before the Board in a timely manner. The Board shall have such other professional, administrative, clerical, and stenographic personnel as are necessary in conducting hearings and considering and disposing of appeals properly before the Board. The Board shall have sufficient personnel under the preceding sentence to enable the Board to conduct hearings and consider and dispose of appeals properly before the Board in a timely manner."],[0,"(b)(1) The Chairman shall be appointed by the President, by and with the advice and consent of the Senate, for a term of six years. The Chairman shall be subject to the same ethical and legal limitations and restrictions concerning involvement in political activities as apply to judges of the United States Court of Appeals for Veterans Claims."],[0,"(2) The Chairman may be removed by the President for misconduct, inefficiency, neglect of duty, or engaging in the practice of law or for physical or mental disability which, in the opinion of the President, prevents the proper execution of the Chairman's duties. The Chairman may not be removed from office by the President on any other grounds. Any such removal may only be made after notice and opportunity for hearing."],[0,"(3) The Chairman may be appointed under this subsection to more than one term. If, upon the expiration of the term of office for which the Chairman was appointed, the position of Chairman would become vacant, the individual serving as Chairman may, with the approval of the Secretary, continue to serve as Chairman until either appointed to another term or a successor is appointed, but not beyond the end of the Congress during which the term of office expired."],[0,"(4) The Secretary shall designate one member of the Board as Vice Chairman. The Vice Chairman shall perform such functions as the Chairman may specify. Such member shall serve as Vice Chairman at the pleasure of the Secretary."],[0,"(c)(1)(A) The Chairman may from time to time designate one or more employees of the Department to serve as acting members of the Board. Except as provided in subparagraph (B), any such designation shall be for a period not to exceed 90 days, as determined by the Chairman."],[0,"(B) An individual designated as an acting member of the Board may continue to serve as an acting member of the Board in the making of any determination on a proceeding for which the individual was designated as an acting member of the Board, notwithstanding the termination of the period of designation of the individual as an acting member of the Board under subparagraph (A) or (C)."],[0,"(C) An individual may not serve as an acting member of the Board for more than 270 days during any one-year period."],[0,"(D) At no time may the number of acting members exceed 20 percent of the total of the number of Board members and acting Board members combined."],[0,"(2) In each annual report to the Congress under section 529 of this title, the Secretary shall provide detailed descriptions of the activities undertaken and plans made in the fiscal year for which the report is made with respect to the authority provided by paragraph (1) of this subsection. In each such report, the Secretary shall indicate, in terms of full-time employee equivalents, the number of acting members of the Board designated under such paragraph (1) during the year for which the report is made."],[0,"(d)(1) After the end of each fiscal year, the Chairman shall prepare a report on the activities of the Board during that fiscal year and the projected activities of the Board for the fiscal year during which the report is prepared and the next fiscal year. Such report shall be included in the documents providing detailed information on the budget for the Department that the Secretary submits to the Congress in conjunction with the President's budget submission for any fiscal year pursuant to section 1105 of title 31."],[0,"(2) Each such report shall include, with respect to the preceding fiscal year, information specifying—"],[1,"(A) the number of cases appealed to the Board during that year;"],[1,"(B) the number of cases pending before the Board at the beginning and at the end of that year;"],[1,"(C) the number of such cases which were filed during each of the 36 months preceding the current fiscal year;"],[1,"(D) the average length of time a case was before the Board between the time of the filing of an appeal and the disposition during the preceding fiscal year;"],[1,"(E) the number of members of the Board at the end of the year and the number of professional, administrative, clerical, stenographic, and other personnel employed by the Board at the end of the preceding fiscal year;"],[1,"(F) the number of employees of the Department designated under subsection (c)(1) to serve as acting members of the Board during that year and the number of cases in which each such member participated during that year; and"],[1,"(G) with respect to hearings scheduled under section 7107(c)(2)(C) of this title—"],[2,"(i) the number of hearings scheduled under such section;"],[2,"(ii) the number of hearings under such section that were cancelled; and"],[2,"(iii) any statistical difference in outcomes between cases heard under such section and those held at the principal location of the Board or by picture and voice transmission at a facility of the Department."],[0,"(3) The projections in each such report for the current fiscal year and for the next fiscal year shall include (for each such year)—"],[1,"(A) an estimate of the number of cases to be appealed to the Board; and"],[1,"(B) an evaluation of the ability of the Board (based on existing and projected personnel levels) to ensure timely disposition of such appeals as required by section 7101(a) of this title."],[0,"(e) A performance incentive that is authorized by law for officers and employees of the Federal Government may be awarded to a member of the Board (including an acting member) by reason of that member's service on the Board only if the Chairman of the Board determines that such member should be awarded that incentive. A determination by the Chairman for such purpose shall be made taking into consideration the quality of performance of the Board member."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/7101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7101. Composition of Board of Veterans' Appeals","tname":"Veterans' Benefits","by":{"0":"2"}},{"t":"usc","label":"38 U.S.C. § 7103","url":"https://www.law.cornell.edu/uscode/text/38/7103","by":{"0":"35"}},{"t":"usc","label":"38 U.S.C. § 7105","url":"https://www.law.cornell.edu/uscode/text/38/7105","subs":["(d)(3)"],"by":{"0":"23"}},{"t":"usc","label":"38 U.S.C. § 7111","url":"https://www.law.cornell.edu/uscode/text/38/7111","by":{"0":"34"}},{"t":"usc","label":"38 U.S.C. § 7251","url":"https://www.law.cornell.edu/uscode/text/38/7251","stext":{"head":"§7251. Status","paras":[[0,"There is hereby established, under Article I of the Constitution of the United States, a court of record to be known as the United States Court of Appeals for Veterans Claims."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/7251?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7251. Status","tname":"Veterans' Benefits","by":{"0":"15"}},{"t":"usc","label":"38 U.S.C. § 7252","url":"https://www.law.cornell.edu/uscode/text/38/7252","subs":["(a)","(b)"],"by":{"0":"2, 15, 25, 15, 22"}},{"t":"usc","label":"38 U.S.C. § 7261","url":"https://www.law.cornell.edu/uscode/text/38/7261","subs":["(a)(4)","(b)","(b)(2)","(c)"],"stext":{"head":"§7261. Scope of review","paras":[[0,"(a) In any action brought under this chapter, the Court of Appeals for Veterans Claims, to the extent necessary to its decision and when presented, shall—"],[1,"(1) decide all relevant questions of law, interpret constitutional, statutory, and regulatory provisions, and determine the meaning or applicability of the terms of an action of the Secretary;"],[1,"(2) compel action of the Secretary unlawfully withheld or unreasonably delayed;"],[1,"(3) hold unlawful and set aside decisions, findings (other than those described in clause (4) of this subsection), conclusions, rules, and regulations issued or adopted by the Secretary, the Board of Veterans' Appeals, or the Chairman of the Board found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or in violation of a statutory right; or"],[2,"(D) without observance of procedure required by law; and"],[1,"(4) in the case of a finding of material fact adverse to the claimant made in reaching a decision in a case before the Department with respect to benefits under laws administered by the Secretary, hold unlawful and set aside or reverse such finding if the finding is clearly erroneous."],[0,"(b) In making the determinations under subsection (a), the Court shall review the record of proceedings before the Secretary and the Board of Veterans' Appeals pursuant to section 7252(b) of this title and shall—"],[1,"(1) take due account of the Secretary's application of section 5107(b) of this title; and"],[1,"(2) take due account of the rule of prejudicial error."],[0,"(c) In no event shall findings of fact made by the Secretary or the Board of Veterans' Appeals be subject to trial de novo by the Court."],[0,"(d) When a final decision of the Board of Veterans' Appeals is adverse to a party and the sole stated basis for such decision is the failure of the party to comply with any applicable regulation prescribed by the Secretary, the Court shall review only questions raised as to compliance with and the validity of the regulation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/7261?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7261. Scope of review","tname":"Veterans' Benefits","by":{"0":"15, 15, 28, 15"}},{"t":"usc","label":"38 U.S.C. § 7266","url":"https://www.law.cornell.edu/uscode/text/38/7266","subs":["(a)"],"stext":{"head":"§7266. Notice of appeal","paras":[[0,"(a) In order to obtain review by the Court of Appeals for Veterans Claims of a final decision of the Board of Veterans' Appeals, a person adversely affected by such decision shall file a notice of appeal with the Court within 120 days after the date on which notice of the decision is issued pursuant to section 7104(e) of this title."],[0,"(b) An appellant shall file a notice of appeal under this section by delivering or mailing the notice to the Court."],[0,"(c) A notice of appeal shall be deemed to be received by the Court as follows:"],[1,"(1) On the date of receipt by the Court, if the notice is delivered."],[1,"(2) On the date of the United States Postal Service postmark stamped on the cover in which the notice is posted, if the notice is properly addressed to the Court and is mailed."],[0,"(d) For a notice of appeal mailed to the Court to be deemed to be received under subsection (c)(2) on a particular date, the United States Postal Service postmark on the cover in which the notice is posted must be legible. The Court shall determine the legibility of any such postmark and the Court's determination as to legibility shall be final and not subject to review by any other Court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/7266?type=usc&year=mostrecent&link-type=html"},"op":5,"ar":1,"head":"§7266. Notice of appeal","tname":"Veterans' Benefits","by":{"0":"4, 7, 13, 23, passim"}},{"t":"usc","label":"38 U.S.C. § 7292","url":"https://www.law.cornell.edu/uscode/text/38/7292","subs":["(a)","(d)"],"stext":{"head":"§7292. Review by United States Court of Appeals for the Federal Circuit","paras":[[0,"(a) After a decision of the United States Court of Appeals for Veterans Claims is entered in a case, any party to the case may obtain a review of the decision with respect to the validity of a decision of the Court on a rule of law or of any statute or regulation (other than a refusal to review the schedule of ratings for disabilities adopted under section 1155 of this title) or any interpretation thereof (other than a determination as to a factual matter) that was relied on by the Court in making the decision. Such a review shall be obtained by filing a notice of appeal with the Court of Appeals for Veterans Claims within the time and in the manner prescribed for appeal to United States courts of appeals from United States district courts."],[0,"(b)(1) When a judge or panel of the Court of Appeals for Veterans Claims, in making an order not otherwise appealable under this section, determines that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that there is in fact a disagreement between the appellant and the Secretary with respect to that question of law and that the ultimate termination of the case may be materially advanced by the immediate consideration of that question, the judge or panel shall notify the chief judge of that determination. Upon receiving such a notification, the chief judge shall certify that such a question is presented, and any party to the case may then petition the Court of Appeals for the Federal Circuit to decide the question. That court may permit an interlocutory appeal to be taken on that question if such a petition is filed with it within 10 days after the certification by the chief judge of the Court of Appeals for Veterans Claims. Neither the application for, nor the granting of, an appeal under this paragraph shall stay proceedings in the Court of Appeals for Veterans Claims, unless a stay is ordered by a judge of the Court of Appeals for Veterans Claims or by the Court of Appeals for the Federal Circuit."],[0,"(2) For purposes of subsections (d) and (e) of this section, an order described in this paragraph shall be treated as a decision of the Court of Appeals for Veterans Claims."],[0,"(c) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction to review and decide any challenge to the validity of any statute or regulation or any interpretation thereof brought under this section, and to interpret constitutional and statutory provisions, to the extent presented and necessary to a decision. The judgment of such court shall be final subject to review by the Supreme Court upon certiorari, in the manner provided in section 1254 of title 28."],[0,"(d)(1) The Court of Appeals for the Federal Circuit shall decide all relevant questions of law, including interpreting constitutional and statutory provisions. The court shall hold unlawful and set aside any regulation or any interpretation thereof (other than a determination as to a factual matter) that was relied upon in the decision of the Court of Appeals for Veterans Claims that the Court of Appeals for the Federal Circuit finds to be—"],[1,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[1,"(B) contrary to constitutional right, power, privilege, or immunity;"],[1,"(C) in excess of statutory jurisdiction, authority, or limitations, or in violation of a statutory right; or"],[1,"(D) without observance of procedure required by law."],[0,"(2) Except to the extent that an appeal under this chapter presents a constitutional issue, the Court of Appeals may not review (A) a challenge to a factual determination, or (B) a challenge to a law or regulation as applied to the facts of a particular case."],[0,"(e)(1) Upon such review, the Court of Appeals for the Federal Circuit shall have power to affirm or, if the decision of the Court of Appeals for Veterans Claims is not in accordance with law, to modify or reverse the decision of the Court of Appeals for Veterans Claims or to remand the matter, as appropriate."],[0,"(2) Rules for review of decisions of the Court of Appeals for Veterans Claims shall be those prescribed by the Supreme Court under section 2072 of title 28."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/7292?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7292. Review by United States Court of Appeals for the Federal Circuit","tname":"Veterans' Benefits","by":{"0":"3, 20, 3, 16"}},{"t":"usc","label":"42 U.S.C. § 405","url":"https://www.law.cornell.edu/uscode/text/42/405","subs":["(g)"],"stext":{"head":"§405. Evidence, procedure, and certification for payments","paras":[[0,"(a) Rules and regulations; procedures"],[0,"The Commissioner of Social Security shall have full power and authority to make rules and regulations and to establish procedures, not inconsistent with the provisions of this subchapter, which are necessary or appropriate to carry out such provisions, and shall adopt reasonable and proper rules and regulations to regulate and provide for the nature and extent of the proofs and evidence and the method of taking and furnishing the same in order to establish the right to benefits hereunder."],[0,"(b) Administrative determination of entitlement to benefits; findings of fact; hearings; investigations; evidentiary hearings in reconsiderations of disability benefit terminations; subsequent applications"],[0,"(1) The Commissioner of Social Security is directed to make findings of fact, and decisions as to the rights of any individual applying for a payment under this subchapter. Any such decision by the Commissioner of Social Security which involves a determination of disability and which is in whole or in part unfavorable to such individual shall contain a statement of the case, in understandable language, setting forth a discussion of the evidence, and stating the Commissioner's determination and the reason or reasons upon which it is based. Upon request by any such individual or upon request by a wife, divorced wife, widow, surviving divorced wife, surviving divorced mother, surviving divorced father, husband, divorced husband, widower, surviving divorced husband, child, or parent who makes a showing in writing that his or her rights may be prejudiced by any decision the Commissioner of Social Security has rendered, the Commissioner shall give such applicant and such other individual reasonable notice and opportunity for a hearing with respect to such decision, and, if a hearing is held, shall, on the basis of evidence adduced at the hearing, affirm, modify, or reverse the Commissioner's findings of fact and such decision. Any such request with respect to such a decision must be filed within sixty days after notice of such decision is received by the individual making such request. The Commissioner of Social Security is further authorized, on the Commissioner's own motion, to hold such hearings and to conduct such investigations and other proceedings as the Commissioner may deem necessary or proper for the administration of this subchapter. In the course of any hearing, investigation, or other proceeding, the Commissioner may administer oaths and affirmations, examine witnesses, and receive evidence. Evidence may be received at any hearing before the Commissioner of Social Security even though inadmissible under rules of evidence applicable to court procedure."],[0,"(2) In any case where—"],[1,"(A) an individual is a recipient of disability insurance benefits, or of child's, widow's, or widower's insurance benefits based on disability,"],[1,"(B) the physical or mental impairment on the basis of which such benefits are payable is found to have ceased, not to have existed, or to no longer be disabling, and"],[1,"(C) as a consequence of the finding described in subparagraph (B), such individual is determined by the Commissioner of Social Security not to be entitled to such benefits,"],[0,"any reconsideration of the finding described in subparagraph (B), in connection with a reconsideration by the Commissioner of Social Security (before any hearing under paragraph (1) on the issue of such entitlement) of the Commissioner's determination described in subparagraph (C), shall be made only after opportunity for an evidentiary hearing, with regard to the finding described in subparagraph (B), which is reasonably accessible to such individual. Any reconsideration of a finding described in subparagraph (B) may be made either by the State agency or the Commissioner of Social Security where the finding was originally made by the State agency, and shall be made by the Commissioner of Social Security where the finding was originally made by the Commissioner of Social Security. In the case of a reconsideration by a State agency of a finding described in subparagraph (B) which was originally made by such State agency, the evidentiary hearing shall be held by an adjudicatory unit of the State agency other than the unit that made the finding described in subparagraph (B). In the case of a reconsideration by the Commissioner of Social Security of a finding described in subparagraph (B) which was originally made by the Commissioner of Social Security, the evidentiary hearing shall be held by a person other than the person or persons who made the finding described in subparagraph (B)."],[0,"(3)(A) A failure to timely request review of an initial adverse determination with respect to an application for any benefit under this subchapter or an adverse determination on reconsideration of such an initial determination shall not serve as a basis for denial of a subsequent application for any benefit under this subchapter if the applicant demonstrates that the applicant, or any other individual referred to in paragraph (1), failed to so request such a review acting in good faith reliance upon incorrect, incomplete, or misleading information, relating to the consequences of reapplying for benefits in lieu of seeking review of an adverse determination, provided by any officer or employee of the Social Security Administration or any State agency acting under section 421 of this title."],[0,"(B) In any notice of an adverse determination with respect to which a review may be requested under paragraph (1), the Commissioner of Social Security shall describe in clear and specific language the effect on possible entitlement to benefits under this subchapter of choosing to reapply in lieu of requesting review of the determination."],[0,"(c) Wage records"],[0,"(1) For the purposes of this subsection—"],[1,"(A) The term \"year\" means a calendar year when used with respect to wages and a taxable year when used with respect to self-employment income."],[1,"(B) The term \"time limitation\" means a period of three years, three months, and fifteen days."],[1,"(C) The term \"survivor\" means an individual's spouse, surviving divorced wife, surviving divorced husband, surviving divorced mother, surviving divorced father, child, or parent, who survives such individual."],[1,"(D) The term \"period\" when used with respect to self-employment income means a taxable year and when used with respect to wages means—"],[2,"(i) a quarter if wages were reported or should have been reported on a quarterly basis on tax returns filed with the Secretary of the Treasury or his delegate under section 6011 of the Internal Revenue Code of 1986 or regulations thereunder (or on reports filed by a State under section 418(e) 1 of this title (as in effect prior to December 31, 1986) or regulations thereunder),"],[2,"(ii) a year if wages were reported or should have been reported on a yearly basis on such tax returns or reports, or"],[2,"(iii) the half year beginning January 1 or July 1 in the case of wages which were reported or should have been reported for calendar year 1937."],[0,"(2)(A) On the basis of information obtained by or submitted to the Commissioner of Social Security, and after such verification thereof as the Commissioner deems necessary, the Commissioner of Social Security shall establish and maintain records of the amounts of wages paid to, and the amounts of self-employment income derived by, each individual and of the periods in which such wages were paid and such income was derived and, upon request, shall inform any individual or his survivor, or the legal representative of such individual or his estate, of the amounts of wages and self-employment income of such individual and the periods during which such wages were paid and such income was derived, as shown by such records at the time of such request."],[0,"(B)(i) In carrying out the Commissioner's duties under subparagraph (A) and subparagraph (F), the Commissioner of Social Security shall take affirmative measures to assure that social security account numbers will, to the maximum extent practicable, be assigned to all members of appropriate groups or categories of individuals by assigning such numbers (or ascertaining that such numbers have already been assigned):"],[1,"(I) to aliens at the time of their lawful admission to the United States either for permanent residence or under other authority of law permitting them to engage in employment in the United States and to other aliens at such time as their status is so changed as to make it lawful for them to engage in such employment;"],[1,"(II) to any individual who is an applicant for or recipient of benefits under any program financed in whole or in part from Federal funds including any child on whose behalf such benefits are claimed by another person; and"],[1,"(III) to any other individual when it appears that he could have been but was not assigned an account number under the provisions of subclauses (I) or (II) but only after such investigation as is necessary to establish to the satisfaction of the Commissioner of Social Security, the identity of such individual, the fact that an account number has not already been assigned to such individual, and the fact that such individual is a citizen or a noncitizen who is not, because of his alien status, prohibited from engaging in employment;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/405?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§405. Evidence, procedure, and certification for payments","tname":"The Public Health and Welfare","by":{"0":"14, 16, 17"}},{"t":"usc","label":"42 U.S.C. § 1997e","url":"https://www.law.cornell.edu/uscode/text/42/1997e","subs":["(a)"],"by":{"0":"12"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(f)(1)"],"by":{"0":"12"}},{"t":"usc","label":"42 U.S.C. § 2000e-16","url":"https://www.law.cornell.edu/uscode/text/42/2000e-16","subs":["(c)"],"by":{"0":"14"}},{"t":"rule","label":"Fed. R. Civ. P. 3","url":"https://www.law.cornell.edu/rules/frcp/rule_3","by":{"0":"17"}},{"t":"rule","label":"Fed. R. Crim. P. 33","url":"https://www.law.cornell.edu/rules/frcrmp/rule_33","by":{"0":"10"}}]};